__global__ void conv_transpose2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int groups
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int output_h = blockIdx.z * blockDim.x + threadIdx.x;
    int output_w = threadIdx.y;

    if (output_h >= output_height || output_w >= output_width || batch_idx >= batch_size || channel_idx >= out_channels) {
        return;
    }

    // Calculate group information
    int channels_per_group = out_channels / groups;
    int group_id = channel_idx / channels_per_group;

    // Initialize accumulator
    float sum = 0.0f;

    // Perform convolution transpose operation
    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            // Calculate input coordinates
            int input_h = output_h * stride - padding + kh;
            int input_w = output_w * stride - padding + kw;

            // Check bounds
            if (input_h >= 0 && input_h < input_height && input_w >= 0 && input_w < input_width) {
                // Calculate indices
                int input_idx = batch_idx * (in_channels * input_height * input_width) +
                               (channel_idx % channels_per_group) * (input_height * input_width) +
                               input_h * input_width + input_w;

                int weight_idx = channel_idx * (in_channels / groups * kernel_size * kernel_size) +
                                (channel_idx % channels_per_group) * (kernel_size * kernel_size) +
                                kh * kernel_size + kw;

                sum += __half2float(input[input_idx]) * __half2float(weight[weight_idx]);
            }
        }
    }

    // Write result
    int output_idx = batch_idx * (out_channels * output_height * output_width) +
                     channel_idx * (output_height * output_width) +
                     output_h * output_width + output_w;

    output[output_idx] = __float2half(sum);
}

// Wrapper function to launch kernel
extern "C" void launch_conv_transpose2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int groups
) {
    dim3 block_size(16, 16);
    dim3 grid_size(batch_size, out_channels, (output_height + 15) / 16);

    conv_transpose2d_kernel<<<grid_size, block_size>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_height, input_width,
        output_height, output_width,
        kernel_size, stride, padding, groups
    );

    cudaDeviceSynchronize();
}
"""

