    # Compile the CUDA extension
    module = load_inline(
        name="conv_transpose2d_ext",
        cpp_sources=[],
        cuda_sources=cuda_source,
        functions=["launch_conv_transpose2d"],
        verbose=True
    )

    return module

# Define the new model class
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # Initialize weights
        self.weight = torch.nn.Parameter(
            torch.randn(out_channels, in_channels // groups, kernel_size, kernel_size),
            requires_grad=True
        )

        if bias:
            self.bias_param = torch.nn.Parameter(torch.zeros(out_channels), requires_grad=True)
        else:
            self.register_parameter('bias_param', None)

        # Compile CUDA extension
        self.module = compile_and_run()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, input_height, input_width = x.shape

        # Calculate output dimensions
        output_height = (input_height - 1) * self.stride - 2 * self.padding + self.kernel_size + self.output_padding
        output_width = (input_width - 1) * self.stride - 2 * self.padding + self.kernel_size + self.output_padding

        # Prepare tensors for CUDA kernel
        input_tensor = x.to(torch.float16)
        weight_tensor = self.weight.to(torch.float16)

        # Create output tensor
        output = torch.empty(
            batch_size, 
            self.out_channels, 
            output_height, 
            output_width,
            dtype=torch.float16,
            device=x.device
        )

        # Launch CUDA kernel
        self.module.launch_conv_transpose2d(
            input_tensor.data_ptr(),
            weight_tensor.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            self.out_channels,
            input_height,
            input_width,
            output_height,
            output_width,
            self.kernel_size,
            self.stride,
            self.padding,
            self.groups
        )

        # Add bias if needed
        if self.bias_param is not None:
            output += self.bias_param.view(1, -1, 1, 1)

        return output

